def seed_site_settings(apps, schema_editor):
    """Singleton aus der Umgebung befüllen, vorhandenes statisches Logo nach
    MEDIA_ROOT verschieben und das contrib.sites-Objekt aktualisieren."""
    SiteSettings = apps.get_model("events", "SiteSettings")
